% TESTRECEIVEDPOWERMAP
% Distribuição de potência óptica recebida: LOS + NLOS.
% TX fixo no centro do teto; RX percorre um plano no piso.

clearvars;
close all;
clc;

%---------------------- Configurações -----------------------------------

params = getChannelParams();
numerical = getNumericalSettings();

% Sala [m].
params.room.length_m = 2;
params.room.width_m = 2;
params.room.height_m = 3;

% Refletividades: xMin, xMax, yMin, yMax.
params.room.wallReflectivity = [0.8, 0.8, 0.8, 0.8];

% TX no centro do teto, apontando para baixo.
params.tx.pose.position_m = [0; 0; params.room.height_m/2];
params.tx.pose.rpy_deg = [0; 0; 0];
params.tx.referenceNormal = [0; 0; -1];

% RX apontando para cima em todas as posições.
params.rx.pose.rpy_deg = [0; 0; 0];
params.rx.referenceNormal = [0; 0; 1];

% Características ópticas.
params.tx.halfPowerAngle_deg = 70;
params.rx.area_m2 = 1e-4;
params.rx.fov_rad = pi/2;
params.rx.filterTransmission = 1;
params.rx.refractiveIndex = 1.5;

params.lightSpeed_m_s = 3e8;

% Discretização das paredes.
numerical.patchesPerMeter = 5;

%---------------------- Configuração do mapa ----------------------------

transmittedPower_W = 20e-3; % Potência óptica constante: 20 mW
rxHeight_m = -params.room.height_m/2;

% Números ímpares incluem a posição central na grade.
nPointsX = 21;
nPointsY = 21;

margin_m = 0.05; % Evita posições exatamente nas paredes

%---------------------- Cálculo -----------------------------------------

map = calculateReceivedPowerMap(params, numerical, ...
    transmittedPower_W, rxHeight_m, nPointsX, nPointsY, margin_m);

%---------------------- Verificações ------------------------------------

assert(all(isfinite(map.receivedPower_W(:))), ...
    'O mapa contém valores não finitos.');

assert(all(map.receivedPower_W(:) >= 0), ...
    'O mapa contém potências negativas.');

% Nesta configuração, esperamos simetria em x e y.
power = map.receivedPower_W;
powerScale = max(power(:));
symmetryTolerance = 1e-10 * max(powerScale, realmin);

differenceX = power - fliplr(power);
differenceY = power - flipud(power);

assert(max(abs(differenceX(:))) <= symmetryTolerance, ...
    'O mapa não apresenta a simetria esperada em x.');

assert(max(abs(differenceY(:))) <= symmetryTolerance, ...
    'O mapa não apresenta a simetria esperada em y.');

%---------------------- Resultados numéricos ----------------------------

centerRow = (nPointsY + 1)/2;
centerCol = (nPointsX + 1)/2;

fprintf('Posições avaliadas: %d\n', numel(power)); %[output:7448dde3]
fprintf('Altura do plano RX: %.2f m\n', rxHeight_m); %[output:056d817a]
fprintf('Potência transmitida: %.2f mW\n', transmittedPower_W * 1e3); %[output:4cd2e7a6]

fprintf('\nPotência recebida no centro:\n'); %[output:11353e62]
fprintf('LOS:   %.6f µW\n', ... %[output:group:2b382594] %[output:2ddfa20c]
    map.powerLOS_W(centerRow, centerCol) * 1e6); %[output:group:2b382594] %[output:2ddfa20c]
fprintf('NLOS:  %.6f µW\n', ... %[output:group:35a4e144] %[output:62c707b5]
    map.powerNLOS_W(centerRow, centerCol) * 1e6); %[output:group:35a4e144] %[output:62c707b5]
fprintf('Total: %.6f µW\n', ... %[output:group:53fa8a17] %[output:382c11b2]
    power(centerRow, centerCol) * 1e6); %[output:group:53fa8a17] %[output:382c11b2]

fprintf('\nPotência mínima no mapa: %.6f µW\n', min(power(:)) * 1e6); %[output:55904604]
fprintf('Potência máxima no mapa: %.6f µW\n', max(power(:)) * 1e6); %[output:264855f9]
fprintf('Verificações de simetria: APROVADAS.\n'); %[output:6f7f70d4]

%---------------------- Gráfico -----------------------------------------

figure('Color', 'w'); %[output:19be1366]

surf(map.X_m, map.Y_m, power * 1e6); %[output:19be1366]

xlabel('Posição x do RX [m]'); %[output:19be1366]
ylabel('Posição y do RX [m]'); %[output:19be1366]
zlabel('Potência óptica recebida [µW]'); %[output:19be1366]

title('Optical power distribution of VLC — LOS + NLOS'); %[output:19be1366]

cb = colorbar; %[output:19be1366]
cb.Label.String = 'Potência óptica recebida [µW]'; %[output:19be1366]

grid on; %[output:19be1366]
axis tight; %[output:19be1366]
view(45, 30); %[output:19be1366]

